//UserControlpublic partial class UserControl1 : UserControl{    MaskedTextBox maskedTextBox;    public UserControl1()    {        InitializeComponent();        maskedTextBox = new MaskedTextBox();    }    [Editor(typeof(MaskEditor), typeof(UITypeEditor))]    public string Mask    {        get { return maskedTextBox.Mask; }        set { maskedTextBox.Mask = value; }    }}//Editorpublic class MaskEditor : UITypeEditor{    public override UITypeEditorEditStyle GetEditStyle(ITypeDescriptorContext context)    {        return UITypeEditorEditStyle.Modal;    }    public override object EditValue(ITypeDescriptorContext context,                                      IServiceProvider provider, object value)    {        var field = context.Instance.GetType().GetField("maskedTextBox",                       System.Reflection.BindingFlags.NonPublic |                        System.Reflection.BindingFlags.Instance);        var maskedTextBox = (MaskedTextBox)field.GetValue(context.Instance);        var maskProperty = TypeDescriptor.GetProperties(maskedTextBox)["Mask"];        var tdc = new TypeDescriptionContext(maskedTextBox, maskProperty);        var editor = (UITypeEditor)maskProperty.GetEditor(typeof(UITypeEditor));        return editor.EditValue(tdc, provider, value);    }}//ITypeDescriptionContext Implementationpublic class TypeDescriptionContext : ITypeDescriptorContext{    private Control editingObject;    private PropertyDescriptor editingProperty;    public TypeDescriptionContext(Control obj, PropertyDescriptor property)    {        editingObject = obj;        editingProperty = property;    }    public IContainer Container    {        get { return editingObject.Container; }    }    public object Instance    {        get { return editingObject; }    }    public void OnComponentChanged()    {    }    public bool OnComponentChanging()    {        return true;    }    public PropertyDescriptor PropertyDescriptor    {        get { return editingProperty; }    }    public object GetService(Type serviceType)    {        return editingObject.Site.GetService(serviceType);    }}//The project may need to be reloaded before Visual Studio can recognize the new UITypeEditor